scripts.command:
$Server=#{art_lateral_1021_001_logonserver}
$User = Join-Path #{art_lateral_1021_001_domain} #{art_lateral_1021_001_username}
$Password="#{art_lateral_1021_001_password}"
cmdkey /generic:TERMSRV/$Server /user:$User /pass:$Password
mstsc /v:$Server
echo "RDP connection established"

scripts.cleanup_command:
Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -name "PortNumber" -Value #{art_lateral_1021_001_old_remote_port}
Remove-NetFirewallRule -DisplayName "RDPPORTLatest-TCP-In" -ErrorAction Ignore 
Get-Service TermService | Restart-Service -Force -ErrorAction Ignore

scripts.command:
Set-PowerCLIConfiguration -InvalidCertificateAction Ignore -ParticipateInCEIP:$false -Confirm:$false 
Connect-VIServer -Server #{art_lateral_1021_004_vm_host} -User #{art_lateral_1021_004_vm_user} -Password #{art_lateral_1021_004_vm_pass}
Get-VMHostService -VMHost #{art_lateral_1021_004_vm_host} | Where-Object {$_.Key -eq "TSM-SSH" } | Start-VMHostService -Confirm:$false

